Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
//
using namespace std;
const int INF = 0x3f3f3f3f;
const int maxm = 2000015;
const int maxn = 105*55;
int n, m, c, d, k;
inline int read()
{
    int x=0,f=1;char ch=getchar();
    while (ch<'0'||ch>'9'){if (ch=='-') f=-1;ch=getchar();}
    while (ch>='0'&&ch<='9'){x=x*10+ch-'0';ch=getchar();}
    return x*f;
}
struct Edge
{
    int to, next, cap, flow, cost;
}edge[maxm];
int head[maxn], tol;
int pre[maxn], dis[maxn];
bool vis[maxn];
int N ;
void init(int n)
{
    N = n;
    tol = 0;
    memset(head, -1, sizeof(head));
}
void addedge(int u, int v, int cap, int cost)
{
    edge[tol].to = v;
    edge[tol].cap = cap;
    edge[tol].cost = cost;
    edge[tol].flow = 0;
    edge[tol].next = head[u];
    head[u] = tol++;
    edge[tol].to = u;
    edge[tol].cap = 0;
    edge[tol].cost = -cost;
    edge[tol].flow = 0;
    edge[tol].next = head[v];
    head[v] = tol++;
}
bool spfa(int s, int t)
{
    queue<int>q;
    for(int i = 0; i < N; i++)
    {
        dis[i] = INF;
        vis[i] = false;
        pre[i] = -1;
    }
    dis[s] = 0;
    vis[s] = true;
    q.push(s);
    while(!q.empty())
    {
        int u = q.front();
        q.pop();
        vis[u] = false;
        for(int i = head[u]; i != -1; i = edge[i].next)
        {
            int v = edge[i].to;
            if(edge[i].cap > edge[i].flow && dis[v] > dis[u] + edge[i].cost)
            {
                dis[v] = dis[u] + edge[i].cost;
                pre[v] = i;
                if(!vis[v])
                {
                    vis[v] = true;
                    q.push(v);
                }
            }
        }
    }
    if(pre[t] == -1) return false;
    else return true;
}
int minCostMaxflow(int s, int t, int &cost)
{
    int flow = 0;
    cost = 0;
    while(spfa(s,t))
    {
        int Min = INF;
        for(int i = pre[t]; i != -1; i = pre[edge[i^1].to])
        {
            if(Min > edge[i].cap - edge[i].flow)
                Min = edge[i].cap - edge[i].flow;
        }
        for(int i = pre[t]; i != -1; i = pre[edge[i^1].to])
        {
            edge[i].flow += Min;
            edge[i^1].flow -= Min;
            cost +=  edge[i].cost*Min;
        }
        flow += Min;
    }
    return flow;
}
int point(int x, int y){
    return (x-1)*50+y;
}
int main(){
    int S = 101*55, T = S + 1;
    n = read(), m = read(), k = read(), c = read(), d = read();
    int tmp;
    init(T+1);
    for(int i = 1; i <= k; i++){
        tmp = read();
        addedge(S, tmp, 1, 0);
    }
    for(int i = 1; i <= 50; i++){
        for(int j = 1; j <= 103; j++){
            int x = point(j, i);
            int y = point(j+1, i);
            addedge(x, y, INF, c);
        }
    }
    for(int i = 0; i < 102; i++){
        int tmp = i*50+1;
        addedge(tmp, T, INF, 0);
    }
    for(int i = 1; i <= m; i++){
        int u, v;
        u = read(), v = read();
        for(int j = 1; j <= 102; j++){
            int x = point(j, u), x1 = point(j+1, u);
            int y1 = point(j+1, v), y = point(j, v);
            for(int k = 0; k < 50; k++){
                int val = d*(k*2+1)+c;
                addedge(x, y1, 1, val);
                addedge(y, x1, 1, val);
            }
        }
    }
    int cost = 0;
    minCostMaxflow(S, T, cost);
    cout << cost << endl;
    return 0;
}
